      if (!REF.test(ref)) throw new Error(`unexpected reference "${ref}"`);
      const url = a.attr("href");
      if (!url) throw new Error(`no link for ${ref}`);
      items.push({
        ref,
        title: text(a.text()),
        url,
        published: isoDate(text($(card).find("time").text())),
      });
    });

