  async list(fetch: Fetch) {
    const items: ListingItem[] = [];
    const first = await fetch("/");
    const $ = load(first);
    const pages = Math.max(
      1,
      ...$("nav.docx-pager a")
        .map((_, a) => Number(text($(a).text())) || 1)
        .get(),
    );
