        const a = p(card).find("h3 a");
        if (!REF.test(ref)) throw new Error(`unexpected reference "${ref}"`);
        items.push({
          ref,
          url: a.attr("href") ?? "",
          title: text(a.text()),
          published: isoDate(text(p(card).find("time").text())),
        });
      });
    }
    return items;
