    for (let i = 0; i < parts.length; i += 2) {
      const dt = parts[i];
      const dd = parts[i + 1];
      if (dt.tagName.toLowerCase() !== "dt" || dd.tagName.toLowerCase() !== "dd")
        throw new Error(`clause list is not dt/dd pairs at item ${i + 1}`);
      const id = text($(dt).text());
